-- cet6 词库 batch1:freq_rank 前 5370 词
-- 生成: node scripts/vocab/ingest-toefl.mjs --bank=cet6 --limit=5370 --emit-sql
-- 数据源: skywind3000/ECDICT · MIT License (c) 2025 Linwei
-- ⚠️ 由 Aaron 执行。脚本本身从不写库。
--
-- 幂等性: vocab_words 走 ON CONFLICT (lower(headword))(索引 vocab_words_headword_uq),
--         vocab_word_banks 走 PK (word_id, bank_id)。重复跑不会产生重复行。
-- bank_id 用子查询取,不硬编码 uuid。

BEGIN;

-- ── 跑之前的基线 ──
SELECT 'BEFORE' AS stage,
       (SELECT count(*) FROM vocab_words) AS words,
       (SELECT count(*) FROM vocab_word_banks
         WHERE bank_id = (SELECT id FROM vocab_banks WHERE code = 'cet6')) AS bank_links;

-- ① 词条
ON CONFLICT (lower(headword)) DO UPDATE
  SET pos        = COALESCE(EXCLUDED.pos, vocab_words.pos),
      freq_rank  = COALESCE(EXCLUDED.freq_rank, vocab_words.freq_rank),
      updated_at = now();

-- ② 挂到 cet6 词库
SELECT w.id, b.id
  FROM vocab_words w
  CROSS JOIN (SELECT id FROM vocab_banks WHERE code = 'cet6') b
 WHERE lower(w.headword) IN ('state', 'system', 'program', 'government', 'point', 'national', 'business', 'issue', 'provide', 'line', 'political', 'lose', 'law', 'include', 'continue', 'later', 'community', 'least', 'president', 'real', 'team', 'social', 'follow', 'centre', 'create', 'public', 'level', 'war', 'history', 'within', 'result', 'win', 'research', 'force', 'offer', 'policy', 'process', 'consider', 'actually', 'probably', 'sense', 'nation', 'interest', 'course', 'experience', 'reach', 'local', 'remain', 'effect', 'perhaps', 'major', 'require', 'role', 'economic', 'effort', 'rate', 'drug', 'leader', 'voice', 'whole', 'military', 'decision', 'explain', 'view', 'relationship', 'federal', 'value', 'international', 'action', 'society', 'tax', 'director', 'position', 'player', 'especially', 'record', 'special', 'space', 'support', 'official', 'site', 'project', 'hit', 'court', 'produce', 'situation', 'industry', 'figure', 'image', 'recent', 'describe', 'product', 'patient', 'test', 'personal', 'technology', 'step', 'type', 'republican', 'organization', 'source', 'cause', 'century', 'evidence', 'culture', 'billion', 'energy', 'realize', 'period', 'available', 'likely', 'opportunity', 'term', 'condition', 'choice', 'rule', 'administration', 'congress', 'campaign', 'material', 'population', 'economy', 'medical', 'risk', 'current', 'involve', 'behavior', 'increase', 'security', 'board', 'seek', 'officer', 'private', 'deal', 'performance', 'fight', 'top', 'goal', 'author', 'represent', 'focus', 'drop', 'upon', 'nature', 'recently', 'reduce', 'movement', 'common', 'share', 'natural', 'race', 'concern', 'series', 'significant', 'response', 'rise', 'decade', 'shoot', 'save', 'scene', 'stock', 'despite', 'central', 'thus', 'treatment', 'protect', 'approach', 'fund', 'serious', 'occur', 'media', 'sign', 'thought', 'list', 'individual', 'quality', 'pressure', 'resource', 'identify', 'mile', 'determine', 'prepare', 'disease', 'whatever', 'success', 'argue', 'recognize', 'pa