-- ── 跑之后的实测 ──
SELECT 'AFTER' AS stage,
       (SELECT count(*) FROM vocab_words) AS words,
       (SELECT count(*) FROM vocab_word_banks
         WHERE bank_id = (SELECT id FROM vocab_banks WHERE code = 'cet6')) AS bank_links;

-- ── count-validate:两行都必须是 t,否则 ROLLBACK ──
-- 预期(首次跑,两表都是空的): words = 5370,cet6_links = 5370
SELECT 'words = 5370' AS expect,
       (SELECT count(*) FROM vocab_words) = 5370 AS ok
UNION ALL
SELECT 'cet6_links = 5370',
       (SELECT count(*) FROM vocab_word_banks
         WHERE bank_id = (SELECT id FROM vocab_banks WHERE code = 'cet6')) = 5370;

COMMIT;
